// Parse [ourtypes.IQuery] from a map,
// or return an error, if any.
func queryFromMapWithoutDispatch(
	m map[string]interface{},
) (
	result ourtypes.IQuery,
	err error,
) {
	var theSelect *ourtypes.QuerySelect
	var theCondition *ourtypes.LogicalExpression
	var theFilters []ourtypes.IQueryFilter

	foundCondition := false

	for k, v := range m {
		switch k {
		case "$select":
			theSelect, err = parseOptional(QuerySelectFromJsonable(v))

		case "$condition":
			theCondition, err = LogicalExpressionFromJsonable(v)
			foundCondition = true

		case "$filters":
			theFilters, err = parseArray(v, QueryFilterFromJsonable)

		default:
			err = newDeserializationError(
				fmt.Sprintf(
					"Unexpected property: %s",
					k,
				),
			)
			return
		}

		if err != nil {
			mustDeserializationError(err).prependName(k)
			return
		}
	}

	if !foundCondition {
		err = newDeserializationError(
			"The required property '$condition' is missing",
		)
		return
	}

	result = ourtypes.NewQuery(
		theCondition,
	)
	result.SetSelect(
		theSelect,
	)
	result.SetFilters(
		theFilters,
	)

	return
}

